questions.question:
سننشئ برنامجًا يطبع جميع قيم درجات الحرارة السبعة على وحدة التحكم.
أدخل البرنامج كما يلي:
for (let degree of degreeList) {
console.log(degree);
}

questions.answer:
نكتب من السطر الثاني الكود التالي

for (let degree of degreeList) {
console.log(degree);
}


الكود كامل

let degreeList = [8, 6, 11, 10, 9, 7, 12];
for (let degree of degreeList) {
console.log(degree);
}

let wordList = ["tomato", "carrot", "onion"];
for (let word of wordList) {
console.log(word);
}

questions.question:
سننشئ برنامجًا يطبع "Big catch" وعدد الأسماك الكبيرة المصطادة كـ "Big fish counter" إذا كان حجم السمكة المصطادة 50 سم أو أكبر.

أدخل برنامجًا مشابهًا لما يلي:
if (fish >= 50) {
console.log("Big catch!！");
big = big + 1;
console.log("Big fish counter:" + big);
}

questions.answer:
مسح او تعديل الكود ليصبح هكذا

let fish = 50;
let big = 0;
if (fish >= 50) {
console.log("Big catch!！");
big = big + 1;
console.log("Big fish counter:" + big);
}

نسخ او تعديل الكود ليصبح هكذا بدون اي تغيير السطر الثالث كما امامك يترك فارغ

let weather = "sunny";
let shop = "OPEN";

if (weather == "sunny") {
if (shop == "OPEN") {
console.log("Buy bread and have a picnic");
}
} else {
console.log("Lunch at home");
}

نسخ او تعديل الكود ليصبح هكذا بدون اي تغيير السطر الثالث كما امامك يترك فارغ

let weather = "sunny";
let group = "Group B";

if (weather == "sunny") {
if (group == "Group A") {
console.log("Destination is the zoo");
} else if (group == "Group B") {
console.log("Destination is the museum");
} else {
console.log("Destination is the art museum");
}
} else {
console.log("Field trip canceled");
}





