questions.question:
حدد نتيجة الإخراج من تنفيذ البرنامج التالي:

let A = 500;
let B = 0;
if (A >= 1) {
B = B + 100;
console.log(B);
}

حدد نتيجة الإخراج من تنفيذ البرنامج التالي:

let weather = "sunny";
let group = "B group";
if (weather == "sunny") {
if (group == "A group") {
console.log("Destination is the park");
} else {
console.log("Destination is the amusement park");
}
} else {
console.log("Destination is the aquarium");
}
